### Script overview:
### (1) Read one-seed trajectory diagnostics generated by
###     `fs_vs_ls_trajectory.R`.
### (2) Create two separate score plots (fixed-step GD and line-search GD),
###     each comparing eta in {5*eta0, 10*eta0}.
### (3) Use consistent color/linetype mapping across both panels so
###     direct visual comparison is straightforward.
### (4) Output files (in `out_dir`):
###     - scoreY_fsGD_{family}_n{n}.pdf
###     - scoreY_lsGD_{family}_n{n}.pdf
###


## some global plotting parameters
textsize <- 29

## get current dir path
### Working directory requirement:
### Set working directory to BTAP before running this script.
### Example: getwd() should return the BTAP folder path.
current_dir <- normalizePath("simulation/Fig 1")

  library(ggplot2)
  library(dplyr)


### User-configurable inputs:
###   n_value_use : network size encoded in the trajectory filename.
###   seed_use    : kept for fixed-step output filename.
###   gdmax_use   : legacy variable; not used in the current trajectory filename convention.
n_value_use <- 1000L
seed_use <- 123L
gdmax_use <- 2000L   ## this is just for the trajectory filename, not for the plot
family_use <- "poisson"  # Family-specific trajectory file to read.

# Family-specific filename produced by the trajectory generator.
traj_file <- file.path(
  current_dir,
  paste0(
    "fs_vs_ls_", family_use,
    "_n", n_value_use,
    "_trajectory.csv"
  )
)
if (!file.exists(traj_file)) {
  stop("Trajectory CSV not found: ", traj_file)
}

out_dir <- current_dir
# Restrict to one family per plot run.

# `df` contains one row per GD iteration and case from the one-seed run.
df <- read.csv(traj_file, stringsAsFactors = FALSE)
n_value <- if ("n" %in% names(df)) unique(df$n)[1] else NA_integer_

# Keep only the two eta levels and the two GD methods for this figure.
eta_keep <- c("5*eta0", "10*eta0")
method_keep <- c("fixed", "linesearch")

# Shared style map: same eta has same aesthetics in both output PDFs.
eta_colors <- c("5*eta0" = "blue", "10*eta0" = "green3")
eta_linetypes <- c("5*eta0" = "solid", "10*eta0" = "22")
eta_labels <- c(
  "5*eta0" = expression(5 * eta[0]),
  "10*eta0" = expression(10 * eta[0])
)

# Subset to relevant family/method/eta and cap to first 2000 iterations for display.
plot_df <- df %>%
  filter(
    family == family_use,
    method %in% method_keep,
    eta_label %in% eta_keep,
    iter <= 2000
  ) %>%
  mutate(
    method = factor(method, levels = method_keep),
    eta_label = factor(eta_label, levels = eta_keep)
  )

# Theme shared by both panels for consistent font sizing and legend placement.
common_theme <- theme_bw(base_size = textsize) +
  theme(
    plot.title = element_blank(),
    plot.margin = margin(2, 2, 0, 2),
    axis.title = element_text(size = textsize),
    axis.text = element_text(size = textsize),
    panel.grid.minor = element_blank(),
    panel.grid.major = element_line(color = "gray92", linewidth = 0.4),
    legend.position = "inside",
    legend.position.inside = c(0.74, 0.78),
    legend.background = element_rect(fill = "white", color = "black"),
    legend.key = element_rect(fill = "white", color = NA),
    legend.key.width = grid::unit(1.8, "cm"),
    legend.key.height = grid::unit(0.7, "cm"),
    legend.text = element_text(size = textsize)
  )

# Function: make_panel
# Purpose:
#   Build one score-vs-iteration plot for a single optimization method.
# Inputs:
#   method_name: "fixed" or "linesearch".
#   y_hi       : upper y-limit for panel-specific score scale.
#   panel_title: kept as an argument for compatibility; plot title is hidden.
# Output:
#   A ggplot object with log-scale x-axis and linear y-axis.
make_panel <- function(method_name, y_hi, panel_title){
  d <- plot_df %>% filter(method == method_name, iter > 0, is.finite(score_max_abs))

  ggplot(d, aes(x = iter, y = score_max_abs, color = eta_label, linetype = eta_label, group = eta_label)) +
    geom_hline(yintercept = 0.01, color = "gray70", linetype = "dotted", linewidth = 1.75) +
    geom_line(linewidth = 1.75, alpha = 0.98, na.rm = TRUE) +
    scale_color_manual(values = eta_colors, labels = eta_labels, drop = FALSE) +
    scale_linetype_manual(values = eta_linetypes, labels = eta_labels, drop = FALSE) +
    scale_x_log10() +
    coord_cartesian(ylim = c(0, y_hi)) +
    labs(
      title = NULL,
      x = "Iteration (log scale)",
      y = "Max Abs Score",
      color = NULL,
      linetype = NULL
    ) +
    guides(
      color = guide_legend(
        override.aes = list(
          linewidth = 1.35,
          linetype = unname(eta_linetypes[eta_keep])
        ),
        keywidth = grid::unit(1.8, "cm")
      ),
      linetype = "none"
    ) +
    common_theme
}

# Fixed-step panel uses larger y-range due to potential score explosion.
p_fixed <- make_panel("fixed", 6600, "Fixed-step GD")
# Keep horizontal grid lines at 500/1000/1500/2000, but label only 1000 and 2000.
p_fixed <- p_fixed + scale_y_continuous(
  breaks = c(2000, 4000, 6000),
  labels = c("2000", "4000","6000")
)
# Line-search panel uses tighter y-range to show convergence behavior clearly.
p_linesearch <- make_panel("linesearch", 200, "Line-search GD")
p_linesearch <- p_linesearch + scale_y_continuous(
  breaks = c(100, 200),
  # labels = c("2000", "4000","6000")
)
# Output filenames for the two separate PDFs.
out_pdf_fixed <- file.path(out_dir, paste0("scoreY_fsGD_", family_use, "_n", n_value, ".pdf"))
out_pdf_ls <- file.path(out_dir, paste0("scoreY_lsGD_", family_use, "_n", n_value, ".pdf"))

# Save each panel as an independent PDF (no combined facet file here).
ggsave(out_pdf_fixed, p_fixed, width = 7.6, height = 4.5, device = cairo_pdf)
ggsave(out_pdf_ls, p_linesearch, width = 7.6, height = 4.5, device = cairo_pdf)

cat("Saved: ", out_pdf_fixed, "\n", sep = "")
cat("Saved: ", out_pdf_ls, "\n", sep = "")
